    char_freq = {}
    for char in string:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # Create a list to store the characters with different frequencies
    different_freq = []
    for char, freq in char_freq.items():
        if freq % 2 != 0:
            different_freq.append(char)

    # Return the string with different frequencies
    return ''.join(different_freq)

