def find_Max_Num(digits):
    max_num = 0
    for i in range(len(digits)):
        for j in range(i+1, len(digits)):
            for k in range(j+1, len(digits)):
                num = digits[i] * 10**i + digits[j] * 10**j + digits[k] * 10**k
                if num > max_num:
                    max_num = num
    return max_num

