def comb_sort(arr):
    n = len(arr)
    gap = n // 2
    while gap > 1:
        gap = gap // 2
        for i in range(0, n - gap):
            for j in range(i + gap, n):
                if arr[i] > arr[j]:
                    arr[i], arr[j] = arr[j], arr[i]
    return arr

