def pancake_sort(arr):
    n = len(arr)
    for i in range(n):
        # Find the maximum element
        max_idx = i
        for j in range(i+1, n):
            if arr[max_idx] < arr[j]:
                max_idx = j
        # Swap the found maximum element with the first element
        arr[i], arr[max_idx] = arr[max_idx], arr[i]
    return arr

