def max_path_sum(triangle, n, m):
    # Create a matrix to store the maximum path sum
    max_sum = [[0 for _ in range(m)] for _ in range(n)]

    # Initialize the first row and column with the values of the triangle
    for i in range(n):
        max_sum[i][0] = triangle[i][0]
        for j in range(m):
            max_sum[i][j] = triangle[i][j]

    # Calculate the maximum path sum for the rest of the rows
    for i in range(1, n):
        for j in range(m):
            max_sum[i][j] = max(max_sum[i-1][j], max_sum[i-1][j+1] + triangle[i][j], max_sum[i-1][j] + triangle[i][j+1])

    # Return the maximum path sum
    return max_sum[n-1][m-1]

