def count_no_of_ways(n, k):
    # Initialize the dp array
    dp = [[0 for _ in range(k+1)] for _ in range(n+1)]

    # Base case
    for i in range(1, n+1):
        for j in range(1, k+1):
            if i == 1 and j == 1:
                dp[i][j] = 1
            elif i == 1:
                dp[i][j] = dp[i-1][j]
            elif j == 1:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j] + dp[i][j-1]

    # Return the result
    return dp[n][k]

