def get_maxgold(matrix, n, m):
    max_gold = 0
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 0:
                for k in range(i, n):
                    for l in range(j, m):
                        if matrix[k][l] > matrix[i][j] + matrix[k][l]:
                            matrix[k][l] = matrix[i][j] + matrix[k][l]
