def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] > x:
            high = mid - 1
        else:
            low = mid + 1
    return -1

def calculate_polygons(x, y, width, height, angle):
    polygons = []
    for i in range(width):
        for j in range(height):
            x1 = x + i * width
            y1 = y + j * height
            x2 = x1 + angle
            y2 = y1 + angle
            polygons.append([x1, y1, x2, y2])
    return polygons

def binary_to_integer(binary):
    result = 0
    for i in range(len(binary)):
        if binary[i] == '1':
            result = result + pow(2, len(binary) - i - 1)
    return result

